require_once __DIR__.'/../includes/bootstrap.php';$email=(string)($_SESSION['pending_registration_email']??'');if($email===''){flash('error','No registration is waiting for verification. Please register again.');redirect('register.php');}$errors=[];$patientCode=null;$orgId=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$code=trim((string)($_POST['code']??''));$q=db()->prepare('SELECT * FROM pending_registrations WHERE email=? AND expires_at>NOW()');$q->execute([$email]);$pending=$q->fetch();if(!$pending){$errors[]='The verification request expired. Please register again.';}elseif((int)$pending['attempts']>=5){$errors[]='Too many incorrect attempts. Please restart registration.';}elseif(!preg_match('/^[0-9]{6}$/',$code)||!password_verify($code,$pending['code_hash'])){$errors[]='That verification code is incorrect.';db()->prepare('UPDATE pending_registrations SET attempts=attempts+1 WHERE id=?')->execute([$pending['id']]);}else{$data=json_decode($pending['payload_json'],true);try{db()->beginTransaction();$method='email';$s=db()->prepare('INSERT INTO users(full_name,email,phone,password_hash,role,status,email_verified_at,phone_verified_at) VALUES(?,?,?,?,?,?,?,?)');$role=$data['type']==='provider'?'hospital_admin':'patient';$status=$role==='patient'?'active':'pending';$s->execute([$data['full_name'],$data['email'],$data['phone'],$data['password_hash'],$role,$status,date('Y-m-d H:i:s'),null]);$uid=(int)db()->lastInsertId();if($role==='patient'){$patientCode='CB-'.strtoupper(bin2hex(random_bytes(4)));db()->prepare('INSERT INTO patient_profiles(user_id,patient_code,phone) VALUES(?,?,?)')->execute([$uid,$patientCode,$data['phone']]);}else{$o=$data['organization'];$s=db()->prepare("INSERT INTO organizations(owner_user_id,name,organization_type,license_number,address,phone,approval_status) VALUES(?,?,?,?,?,?,'pending')");$s->execute([$uid,$o['name'],$o['organization_type'],$o['license_number'],$o['address'],$o['phone']]);$orgId=(int)db()->lastInsertId();if(!empty($o['verification_document']['stored_filename'])){$doc=$o['verification_document'];db()->prepare('INSERT INTO organization_verification_documents(organization_id,stored_filename,original_filename,mime_type,file_size) VALUES(?,?,?,?,?)')->execute([$orgId,$doc['stored_filename'],$doc['original_filename'],$doc['mime_type'],(int)$doc['file_size']]);}db()->prepare("INSERT INTO organization_members(organization_id,user_id,member_role,status) VALUES(?,?,'hospital_admin','active')")->execute([$orgId,$uid]);}
db()->prepare('DELETE FROM pending_registrations WHERE email=?')->execute([$email]);db()->commit();unset($_SESSION['pending_registration_email']);if($role==='patient'){send_carebridge_email($email,'Welcome to CareBridge — your Patient ID','Your account is verified','Your patient account is now ready. Keep your Patient ID safe.',['Patient ID'=>$patientCode]);flash('success','Email verified. Your Patient ID is '.$patientCode.'. You can now log in.');redirect('login-patient.php');}send_carebridge_email($email,'CareBridge provider application received','Application received','Your contact is verified and your organization application is awaiting approval. You will be notified after review.',['Organization'=>$data['organization']['name'],'Application reference'=>'CB-H'.str_pad((string)$orgId,6,'0',STR_PAD_LEFT),'Status'=>'Pending review']);flash('success','Email verified. Your provider application is pending review.');redirect('login-provider.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();error_log((string)$e);$errors[]='We could not finish registration. Please retry or contact the administrator.';}}}
$pageTitle='Verify registration';require __DIR__.'/../includes/header.php';?><section class="auth-layout"><div class="auth-aside"><span class="eyebrow">ONE MORE STEP</span><h1>Verify your contact.</h1><p>Your registration is not completed until the verification code is confirmed.</p></div><div class="form-panel"><div class="form-heading"><h2>Enter verification code</h2><p>Sent to your registered email address.</p></div><?php if($errors):?><div class="alert alert-error"><ul><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post" class="stack-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>6-digit code<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" minlength="6" maxlength="6" required autofocus></label><button class="button button-full" type="submit">Verify & create account →</button></form><p class="form-hint">Codes expire after 10 minutes. If it expires, restart registration to request a new code.</p></div></section><?php require __DIR__.'/../includes/footer.php';?>